<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Hex Encoder & Decoder','description'=>'Convert text to hexadecimal or decode hexadecimal text locally.','url'=>'https://smarttoolz.in/tools/hex-encoder/']; smarttoolz_tool_page_start($tool); ?><main class="tool"><h1>Hex Encoder & Decoder</h1><p>Convert text to hexadecimal and back instantly.</p><textarea id="i" placeholder="Enter text or hex"></textarea><button id="e">Text → Hex</button><button id="d">Hex → Text</button><textarea id="o" readonly></textarea></main><style>.tool{max-width:760px;margin:60px auto;padding:24px}.tool textarea{width:100%;box-sizing:border-box;min-height:140px;margin:8px 0;padding:14px;border:1px solid #ddd;border-radius:12px}.tool button{padding:11px 16px;margin:4px;border:0;border-radius:10px;background:#5541ff;color:#fff;font-weight:800}</style><script>e.onclick=()=>o.value=Array.from(new TextEncoder().encode(i.value)).map(x=>x.toString(16).padStart(2,'0')).join('');d.onclick=()=>{try{let x=i.value.replace(/\s/g,'');if(x.length%2)throw 0;o.value=new TextDecoder().decode(new Uint8Array(x.match(/../g).map(h=>parseInt(h,16))))}catch(x){o.value='Invalid hexadecimal input.'}}</script><?php smarttoolz_tool_page_end(); ?>